#include <iostream>

int main() {
    unsigned int u = 10;  // Initialize unsigned integer
    // Problematic for loop: Demonstrates infinite loop due to always-true condition
    for (; u >= 0; --u) {
        std::cout << u << std::endl;  // This will print values and loop forever after underflow
    }
    // Safer while loop alternative: Ensures condition is checked before decrement
    u = 10;  // Reset for demonstration
    while (u > 0) {
        std::cout << u << std::endl;  // Prints 10 down to 1
        --u;  // Decrement after action, and check condition next iteration
    }
    return 0;
}
